import 'dart:convert';
import 'local_database.dart';
class PawRepository {
 PawRepository(this.db);final LocalDatabase db;
 static const tables=['pets','reminders','care_logs','pet_records','feeding_entries','activity_entries','contacts','checklists','favorites','collections','reading_history'];
 Future<void> save(String table,Map<String,Object?> value)async{if(!tables.contains(table))throw ArgumentError('Unsupported table');await db.put(table,value['id'] as String,value['petId'] as String?,jsonEncode(value));}
 Future<List<Map<String,dynamic>>> list(String table,{String? petId})async{if(!tables.contains(table))throw ArgumentError('Unsupported table');final rows=await db.all(table,petId:petId);return rows.map((r)=>Map<String,dynamic>.from(jsonDecode(r['payload'] as String) as Map)).toList();}
 Future<void> delete(String table,String id)=>db.remove(table,id);
 Future<void> deletePet(String id)=>db.removePet(id);
 Future<Map<String,List<Map<String,dynamic>>>> validateImport(String source)async{if(source.length>10*1024*1024)throw FormatException('Backup is larger than 10 MB.');final decoded=jsonDecode(source);if(decoded is! Map||decoded['schema_version']!=2)throw FormatException('Unsupported backup version.');final result=<String,List<Map<String,dynamic>>>{};final petIds=<String>{};for(final table in tables){final raw=decoded[table]??const [];if(raw is! List||raw.length>20000)throw FormatException('Invalid $table collection.');final values=<Map<String,dynamic>>[];final ids=<String>{};for(final item in raw){if(item is! Map||item['id'] is! String||item['id'].toString().isEmpty)throw FormatException('Invalid record in $table.');final value=Map<String,dynamic>.from(item);if(value.containsKey('photoPath'))value['photoPath']='';if(value.containsKey('attachmentPath'))value['attachmentPath']='';if(!ids.add(value['id'] as String))throw FormatException('Duplicate ID in $table.');values.add(value);}result[table]=values;if(table=='pets')petIds.addAll(values.map((e)=>e['id'] as String));}
 for(final table in ['reminders','care_logs','pet_records','feeding_entries','activity_entries','contacts','checklists']){for(final item in result[table]??const []){final petId=item['petId'];if(petId!=null&&(petId is! String||!petIds.contains(petId)))throw FormatException('A $table entry references a missing pet.');if(['reminders','care_logs','pet_records','feeding_entries','activity_entries'].contains(table)&&petId==null)throw FormatException('A $table entry must reference a pet.');}}
 final rawPreferences=decoded['preferences']??const {};if(rawPreferences is! Map)throw FormatException('Invalid preferences section.');const allowedPreferences={'selected_pet','weight_unit','distance_unit','temperature_unit','locale','onboarding_complete','interest_dog','interest_cat','legacy_preferences_migrated'};final preferences=<String,dynamic>{};for(final entry in rawPreferences.entries){if(entry.key is! String||!allowedPreferences.contains(entry.key)||entry.value is! String)throw FormatException('Unsupported preference entry.');preferences[entry.key as String]=entry.value;}final selected=preferences['selected_pet'];if(selected is String&&selected.isNotEmpty&&!petIds.contains(selected))throw FormatException('Selected pet is not present in this backup.');result['__preferences__']=[preferences];return result;}
 Future<void> restore(Map<String,List<Map<String,dynamic>>> records,{required bool replaceExisting})async{await db.restoreAll(records,replaceExisting:replaceExisting);}
 Future<String> exportAll()async{final data=<String,dynamic>{'schema_version':2,'app':'PawPal','exported_at':DateTime.now().toUtc().toIso8601String()};for(final table in tables){final rows=await list(table);for(final row in rows){if(row.containsKey('photoPath'))row['photoPath']='';if(row.containsKey('attachmentPath'))row['attachmentPath']='';}data[table]=rows;}final preferenceKeys=['selected_pet','weight_unit','distance_unit','temperature_unit','locale','onboarding_complete','interest_dog','interest_cat','legacy_preferences_migrated'];final preferences=<String,String>{};for(final key in preferenceKeys){final value=await db.getPreference(key);if(value!=null)preferences[key]=value;}data['preferences']=preferences;return const JsonEncoder.withIndent('  ').convert(data);}
}
